import { useRef, useEffect } from "react";
import Typed from "typed.js";
import "../App.css";
import AOS from "aos";
import "aos/dist/aos.css";

function HeaderFormat() {
  const el = useRef(null);

  useEffect(() => {
    // Initialize typed animation
    const typed = new Typed(el.current, {
      strings: [
        "Download YouTube Videos",
        "Save Videos in HD or MP3",
        "Fast, Secure and Free"
      ],
      typeSpeed: 60,
      backSpeed: 25,
      loop: true,
    });

    // Cleanup
    return () => typed.destroy();
  }, []);

  useEffect(() => {
    AOS.init({
      once: true,
      duration: 1000,
      easing: "ease-out",
    });
  }, []);

  return (
    <header className="text-center header" aria-label="YouTube Downloader Header">
      <div className="header-content" data-aos="fade-up">
        <h1 className="highlight main-title">
          YouTube <span className="highlight">Download Pro</span>
        </h1>

        <div className="type-wrap">
          <span ref={el} aria-hidden="true"></span>
        </div>
      </div>
    </header>
  );
}

export default HeaderFormat;
